import React, { useCallback, useMemo, useState } from 'react';
import {
  Select,
  SearchTextInput,
  detectDateRangePreset,
  dispatchAppToast,
  ErpDataListGrid,
  LIN_ERP_LIST_FILTER_LAYOUT,
  LinErpListFilterBar,
  LinPageLayout,
  useViewMobileLayout,
} from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useAppDispatch } from '../../../store/hooks';
import { useVoucherListFilterState } from '../../../hooks/useVoucherListFilterState';
import { useVoucherListSelection } from '../../../hooks/useVoucherListSelection';
import { bankStatementImportService } from '../../../services/kt/bankStatementImportService';
import type { BankStatementImportVoucherListItem } from '../../../services/kt/bankStatementImportModels';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatDateTimeLocal, formatMoney } from '../../../utils/formatters';
import {
  VOUCHER_LIST_ROW_MENU_HINT_DESKTOP,
  VOUCHER_LIST_ROW_MENU_HINT_TOUCH,
  voucherListRowMenuHintDismissStorageKey,
} from '../../../utils/voucherListRowMenuHint';
import { LIST_FILTER_SCOPE } from '../../../constants/listFilterScopes';
import {
  IMPORT_SAO_KE_LIST_LABELS,
  IMPORT_SAO_KE_PROCESSING_OPTIONS,
  formatImportSaoKeProcessingLevel,
  resolveImportResumeStep,
} from '../../../constants/importSaoKeLabels';
import { KT } from '../../../router/paths';
import erp from '../../../styles/erpPage.module.css';
import styles from './ImportSaoKeListPage.module.css';
import {
  DEFAULT_PAGE_SIZE,
  VoucherListPagination,
  type ListPageSize,
} from '../../../components/list/VoucherListPagination';
import { useVoucherListTableBusy } from '../../../components/list/useVoucherListTableBusy';
import { VoucherRowActionMenu, type VoucherRowMenuAction } from '../../../components/voucher-list';

const PAGE_SIZE = DEFAULT_PAGE_SIZE;
const testIdPrefix = 'kt-import-sao-ke';
const pageId = testIdPrefix;
const labels = IMPORT_SAO_KE_LIST_LABELS;

const ImportSaoKeListPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useInAppNavigate();
  const viewMobile = useViewMobileLayout();

  const {
    initialized,
    fromDate,
    toDate,
    applyDateRange,
    processingLevel,
    setProcessingLevel,
    page,
    setPage,
    resetPage,
  } = useVoucherListFilterState(LIST_FILTER_SCOPE.importSaoKe);

  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [items, setItems] = useState<BankStatementImportVoucherListItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [pageSize, setPageSizeState] = useState<ListPageSize>(PAGE_SIZE);
  const [rowMenu, setRowMenu] = useState<{ x: number; y: number; row: BankStatementImportVoucherListItem } | null>(null);

  const { showTableLoading } = useVoucherListTableBusy(loading);

  const selection = useVoucherListSelection({
    rows: items,
    totalCount,
    page,
    pageSize,
    getRowId: r => r.id,
  });

  const activeRow = selection.activeRow;

  const refresh = useCallback(() => {
    selection.clearSelection();
    setReloadKey(k => k + 1);
  }, [selection]);

  const setPageSize = (size: number) => {
    setPageSizeState(size as ListPageSize);
    resetPage();
    selection.clearSelection();
  };

  React.useEffect(() => {
    if (!initialized) return;
    let cancelled = false;
    setLoading(true);
    const t = window.setTimeout(() => {
      bankStatementImportService.listImportVouchers({
        fromDate,
        toDate,
        processingLevel: processingLevel || undefined,
        search: search || undefined,
        page,
        pageSize,
      })
        .then(res => {
          if (!cancelled) {
            setItems(res.items ?? []);
            setTotalCount(res.totalCount ?? 0);
          }
        })
        .catch(err => {
          if (!cancelled) {
            dispatchAppToast(dispatch, {
              message: getApiErrorMessage(err, labels.listLoadError),
              type: 'error',
            });
          }
        })
        .finally(() => {
          if (!cancelled) setLoading(false);
        });
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [initialized, fromDate, toDate, processingLevel, search, page, pageSize, reloadKey, dispatch]);

  const navigateToRow = useCallback((row: BankStatementImportVoucherListItem) => {
    navigate(`${KT.IMPORT_SAO_KE}/${row.id}`);
  }, [navigate]);

  const handleRowOpenActionMenu = useCallback(
    ({ row, x, y }: { row: BankStatementImportVoucherListItem; x: number; y: number }) => {
      selection.selectActiveRow(row);
      setRowMenu({ x, y, row });
    },
    [selection],
  );

  const handleRowMenuSelect = useCallback(
    (action: VoucherRowMenuAction) => {
      const row = rowMenu?.row;
      if (!row) return;
      if (action === 'view' || action === 'edit') {
        navigateToRow(row);
      }
    },
    [rowMenu?.row, navigateToRow],
  );

  const handleFilterSearch = useCallback(() => {
    setSearch(searchDraft.trim());
    resetPage();
    setReloadKey(k => k + 1);
  }, [searchDraft, resetPage]);

  const continueLabel = (row: BankStatementImportVoucherListItem) => {
    const step = resolveImportResumeStep(row.processingLevel);
    return step === 4 ? labels.continueConfirm : labels.continueClassify;
  };

  const voucherToolbar = useMemo(
    () => ({
      testIdPrefix,
      onRefresh: refresh,
      canView: Boolean(activeRow),
      onView: () => activeRow && navigateToRow(activeRow),
      canEdit: Boolean(activeRow && activeRow.processingLevel !== '5'),
      onEdit: () => activeRow && navigateToRow(activeRow),
      canCreate: true,
      onCreate: () => navigate(KT.IMPORT_SAO_KE_NEW),
    }),
    [activeRow, refresh, navigate, navigateToRow],
  );

  const listFilters = useMemo(
    () => (
      <LinErpListFilterBar
        testIdPrefix={testIdPrefix}
        fromDate={fromDate}
        toDate={toDate}
        onDateChange={(from, to) => {
          applyDateRange(from, to, detectDateRangePreset(from, to) || 'custom');
          resetPage();
        }}
        onSearch={handleFilterSearch}
        loading={showTableLoading}
        leading={(
          <>
            <div data-testid={`${testIdPrefix}-field-processingLevel`}>
              <Select
                label="Mức xử lý"
                value={processingLevel}
                onChange={e => { setProcessingLevel(e.target.value); resetPage(); }}
                options={[...IMPORT_SAO_KE_PROCESSING_OPTIONS]}
                data-testid={`${testIdPrefix}-filter-processingLevel`}
              />
            </div>
            <div data-testid={`${testIdPrefix}-field-search`}>
              <SearchTextInput
                label="Tìm"
                value={searchDraft}
                onChange={setSearchDraft}
                onSearch={handleFilterSearch}
                placeholder="Số CT, người import, TK…"
                testId={`${testIdPrefix}-filter-search`}
              />
            </div>
          </>
        )}
      />
    ),
    [
      fromDate,
      toDate,
      processingLevel,
      searchDraft,
      applyDateRange,
      resetPage,
      setProcessingLevel,
      handleFilterSearch,
      showTableLoading,
    ],
  );

  const rowMenuHintMessage = viewMobile
    ? VOUCHER_LIST_ROW_MENU_HINT_TOUCH
    : VOUCHER_LIST_ROW_MENU_HINT_DESKTOP;

  const listBody = !showTableLoading && items.length === 0 ? (
    <div className={erp.empty}>{labels.empty}</div>
  ) : !showTableLoading ? (
    <ErpDataListGrid
      testIdPrefix={testIdPrefix}
      rows={items}
      page={page}
      pageSize={pageSize}
      selection={selection}
      getRowId={r => r.id}
      onRowDoubleClick={navigateToRow}
      onRowOpenActionMenu={handleRowOpenActionMenu}
      rowMenuHintMessage={rowMenuHintMessage}
      rowMenuHintDismissStorageKey={voucherListRowMenuHintDismissStorageKey(testIdPrefix)}
      enableRowMenuLongPress={viewMobile}
      headerCells={(
        <>
          <th>Số CT</th>
          <th>Thời gian</th>
          <th>Người import</th>
          <th>TK NH</th>
          <th>Kỳ</th>
          <th>Dòng</th>
          <th>Thu</th>
          <th>Chi</th>
          <th>Mức XL</th>
          <th>Đơn vị</th>
          <th>Tiếp tục</th>
        </>
      )}
      renderRow={(row, rowNo) => (
        <>
          <td data-testid={`${testIdPrefix}-row-${rowNo}-code`}>{row.code}</td>
          <td>{formatDateTimeLocal(row.importedAt)}</td>
          <td>{row.importedByName || row.importedByEmployeeCode || '—'}</td>
          <td>{row.defaultBankAccountCode}</td>
          <td>{row.monthCode}</td>
          <td>{row.statementLineCount}</td>
          <td className={erp.colAmount}>{formatMoney(row.totalCredit)}</td>
          <td className={erp.colAmount}>{formatMoney(row.totalDebit)}</td>
          <td>
            <span className={styles.levelBadge}>
              {formatImportSaoKeProcessingLevel(row.processingLevel)}
            </span>
          </td>
          <td>{row.companyCode || '—'}</td>
          <td>
            <button
              type="button"
              className={styles.continueLink}
              data-testid={`${testIdPrefix}-row-${rowNo}-continue`}
              onClick={e => {
                e.stopPropagation();
                navigateToRow(row);
              }}
            >
              {continueLabel(row)}
            </button>
          </td>
        </>
      )}
    />
  ) : null;

  return (
    <div
      className={erp.voucherListRoot}
      data-voucher-list-page
      data-testid={`${testIdPrefix}-list`}
    >
      <LinPageLayout
        kind="voucher"
        testIdPrefix={testIdPrefix}
        pageId={pageId}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{
          title: labels.listPageTitle,
          titleIconClass: 'fas fa-file-import',
          pageId,
        }}
        voucherToolbar={voucherToolbar}
        listTitle={labels.listTitle}
        listRowMenuHelp
        filters={listFilters}
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        showTableLoading={showTableLoading}
        skeletonRows={Math.min(pageSize, 8)}
        footer={(
          <VoucherListPagination
            testIdPrefix={testIdPrefix}
            page={page}
            totalCount={totalCount}
            pageSize={pageSize}
            onPageChange={p => { setPage(p); selection.clearSelection(); }}
            onPageSizeChange={setPageSize}
          />
        )}
        modals={(
          <VoucherRowActionMenu
            open={Boolean(rowMenu)}
            x={rowMenu?.x ?? 0}
            y={rowMenu?.y ?? 0}
            onClose={() => setRowMenu(null)}
            onSelect={handleRowMenuSelect}
            testIdPrefix={testIdPrefix}
            showView
            showEdit={Boolean(rowMenu?.row && rowMenu.row.processingLevel !== '5')}
            showViewLedger={false}
            showPrint={false}
          />
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default ImportSaoKeListPage;
